class Solution {
  public int minimumDiameterAfterMerge(int[][] edges1, int[][] edges2) {
    int d1 = diameter(edges1), d2 = diameter(edges2);
    // join the two centres: the new longest path is either old diameter or the two radii plus the
    // new edge
    return Math.max(Math.max(d1, d2), (d1 + 1) / 2 + (d2 + 1) / 2 + 1);
  }

  private int diameter(int[][] edges) {
    int n = edges.length + 1;
    List<Integer>[] graph = new List[n];
    for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
    for (int[] e : edges) {
      graph[e[0]].add(e[1]);
      graph[e[1]].add(e[0]);
    }
    int[] far = bfs(graph, 0);
    return bfs(graph, far[0])[1];
  }

  // farthest node from start and its distance
  private int[] bfs(List<Integer>[] graph, int start) {
    int[] dist = new int[graph.length];
    Arrays.fill(dist, -1);
    int[] queue = new int[graph.length];
    int head = 0, tail = 0, last = start;
    queue[tail++] = start;
    dist[start] = 0;
    while (head < tail) {
      int u = queue[head++];
      last = u;
      for (int v : graph[u]) {
        if (dist[v] < 0) {
          dist[v] = dist[u] + 1;
          queue[tail++] = v;
        }
      }
    }
    return new int[] {last, dist[last]};
  }
}
